}

input.new_string:
#show heading: it => {
  if it.level == 1 {
    v(1.2em)
    align(left)[#text(16pt, weight: "bold")[#it.body]]
    v(0.3em)
    line(length: 100%, stroke: 1.5pt)
    v(0.6em)
  } else if it.level == 2 {
    v(0.9em)
    align(left)[#text(13pt, weight: "bold", fill: rgb("#2c4a6e"))[#it.body]]
    v(0.4em)
  } else if it.level == 3 {
    v(0.6em)
    align(left)[#text(11pt, weight: "bold", fill: rgb("#4a3728"))[#it.body]]
    v(0.3em)
  }
}

